from __future__ import annotations

from typing import Any

_ALIGNER_ID = "qwen3-forced-aligner-0.6b"


def _yue_want_singing_post(
    lang: str | None,
    vad_options: dict[str, Any] | None,
    *,
    singing_karaoke: bool | None = None,
) -> bool:
    """Cantonese song/MV post (merge/stretch) — not spoken dialogue.

    Builtin ``zh-yue-qwen3-song`` uses VAD threshold≈0.45 / minSpeech≈250ms;
    dialogue film defaults are 0.55 / 350ms. Explicit ``singingKaraoke`` wins
    even when job language is still ``auto`` (UI form may not have applied yue).
    """
    if singing_karaoke is True:
        return True
    if singing_karaoke is False:
        return False
    lang_l = str(lang or "").strip().lower()
    if lang_l not in ("cantonese", "yue"):
        return False
    opts = vad_options if isinstance(vad_options, dict) else {}

    def _num(*keys: str, default: float = 0.0) -> float:
        for key in keys:
            if key not in opts or opts[key] is None:
                continue
            try:
                return float(opts[key])
            except Exception:
                continue
        return float(default)

    thr = _num("threshold", "vadThreshold", default=0.0)
    min_speech = _num(
        "min_speech_ms",
        "minSpeechMs",
        "minSpeechDurationMs",
        default=0.0,
    )
    return 0.40 <= thr <= 0.50 and 200.0 <= min_speech <= 300.0


def wants_forced_aligner(timing_align_model: str | None) -> bool:
    """True when job explicitly requests Qwen ForcedAligner word timestamps."""
    raw = str(timing_align_model or "").strip().lower().replace("_", "-")
    if not raw:
        return False
    if raw in (
        "ten",
        "ten-vad",
        "vad",
        "auto",
        "firered",
        "firered-vad",
        "fire-red",
        "fireredvad",
        "off",
        "rate",
        "none",
        "cps",
    ):
        return False
    if raw == _ALIGNER_ID or raw.startswith("qwen3-forced"):
        return True
    if "align" in raw:
        return True
    return False


def _aligner_island_backend(
    vad_model: str | None,
    timing_align_model: str | None,
) -> str:
    """When ForcedAligner is on, always prefer VAD islands (never primary 90s windows).

    Soft-AV Qwen on fixed windows often returns only ``…`` and drops dialogue
    (NAAC-076). FireRed catalog VAD / firered hint → FireRed islands; otherwise
    TEN (same geometry as the Galgame TEN preset).
    """
    vad = str(vad_model or "").strip().lower().replace("_", "-")
    raw = str(timing_align_model or "").strip().lower().replace("_", "-")
    if "firered" in vad or "firered" in raw:
        return "firered"
    return "ten"


def _island_vad_backend(timing_align_model: str | None) -> str | None:
    """``ten`` | ``firered`` | ``None`` (fixed windows)."""
    if timing_align_model is None:
        return "ten"
    raw = str(timing_align_model).strip().lower().replace("_", "-")
    if raw == "":
        return None
    if wants_forced_aligner(timing_align_model):
        return None
    if raw in ("firered", "firered-vad", "fire-red", "fireredvad"):
        return "firered"
    if raw in ("ten", "ten-vad", "vad", "auto"):
        return "ten"
    return "ten"
